import sys
import math

class Task:
    def __init__(self):
        self.mod = 998244353
        self.stirlingCache = None

    def add(self, a, b):
        c = a + b
        if c >= self.mod:
            return c - self.mod
        if c < 0:
            return c + self.mod
        return c

    def mult(self, a, b):
        return (a * b) % self.mod

    def mult_multiple(self, *x):
        result = 1
        for val in x:
            result = self.mult(result, val)
        return result

    def generateStirling(self):
        size = 5001
        self.stirlingCache = [[0] * size for _ in range(size)]
        for i in range(size):
            self.stirlingCache[i][0] = 0
        for i in range(size):
            self.stirlingCache[i][i] = 1
        for i in range(2, size):
            for j in range(1, i):
                self.stirlingCache[i][j] = self.add(
                    self.mult(self.stirlingCache[i - 1][j], i - 1),
                    self.stirlingCache[i - 1][j - 1]
                )

    def runAlgorithm(self, sc, pw):
        self.generateStirling()
        n = int(sc.next())
        m = int(sc.next())
        k = int(sc.next())
        invM = pow(m, -1, self.mod)
        pValues = [0] * 5001
        pValues[0] = 1
        currentN = n
        accumulatedProduct = 1
        for i in range(1, k + 1):
            accumulatedProduct = self.mult_multiple(accumulatedProduct, currentN, invM)
            currentN -= 1
            total = accumulatedProduct
            for j in range(i - 1, 0, -1):
                signFlag = 1 if ((i - j) % 2 == 1) else -1
                total = self.add(total, self.mult(self.stirlingCache[i][j], self.add(0, signFlag * pValues[j])))
            pValues[i] = total
        pw.write(str(pValues[k]) + "\n")

class Scanner:
    def __init__(self, stream):
        self.tokens = []
        self.stream = stream

    def next(self):
        while not self.tokens:
            line = self.stream.readline()
            if not line:
                return ''
            self.tokens = line.strip().split()
        return self.tokens.pop(0)

    def nextInt(self):
        return int(self.next())

def main():
    sc = Scanner(sys.stdin)
    class Pw:
        def __init__(self):
            self.output = []

        def write(self, s):
            self.output.append(s)

        def close(self):
            sys.stdout.write(''.join(self.output))
    pw = Pw()
    task = Task()
    task.runAlgorithm(sc, pw)
    pw.close()

if __name__ == "__main__":
    main()

